// Extract and normalize incoming candidate payload
const body = $json.body || $json;

// 1. Normalize Phone Number
let phone = String(body.phone || body.phone_number || '').replace(/\D/g, '');
if (phone.length === 12 && phone.startsWith('91')) {
  phone = phone.substring(2);
} else if (phone.length === 11 && phone.startsWith('0')) {
  phone = phone.substring(1);
}

// 2. Normalize Email
const email = (body.email || body.email_id || '').trim().toLowerCase();

// 3. Normalize Name
const name = (body.name || body.full_name || body.worker_name || 'Anonymous Candidate').trim();

// 4. Skills
const skills = body.skills || body.skill_tags || 'General';

return {
  json: {
    raw_name: name,
    phone: phone,
    email: email,
    city: body.city || body.location || 'Unknown',
    experience_years: Number(body.experience_years || body.experience || 0),
    skills: skills,
    received_at: new Date().toISOString()
  }
};

